mapper.select:
SELECT 
FROM agent_trace_session
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY started_at DESC, created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM agent_trace_session
WHERE user_id = #{userId}

    AND status = #{status}

SELECT id
FROM agent_trace_session
WHERE status = 'RUNNING'
  AND started_at < #{cutoff}
ORDER BY started_at
LIMIT #{limit}

mapper.delete:
DELETE FROM agent_trace_session
WHERE started_at < #{cutoff}
ORDER BY started_at
LIMIT #{limit}
